package com.martinfjohansen.oneaccounting.BasicPixelFont.BasicPixelFont;

import com.martinfjohansen.oneaccounting.RGBABitmapImage.RGBABitmapImage.RGBA;
import com.martinfjohansen.oneaccounting.RGBABitmapImage.RGBABitmapImage.RGBABitmapImage;

import static com.martinfjohansen.oneaccounting.Graphics2D.Graphics2D.Graphics2D.DrawPixel;

public class BasicPixelFont{
	public static char [] GetPixelFontData(){
		return "".toCharArray();
	}

	public static void DrawAsciiCharacter(RGBABitmapImage image, double topx, double topy, char a, RGBA color){
		double index, x, y, pixel, basis, ybasis;
		char [] allCharData;

		index = a;
		index = index - 32d;
		allCharData = GetPixelFontData();

		basis = index*8d*13d;

		for(y = 0d; y < 13d; y = y + 1d){
			ybasis = basis + y*8d;
			for(x = 0d; x < 8d; x = x + 1d){
				pixel = allCharData[(int)(ybasis + x)];
				if(pixel == '1'){
					DrawPixel(image, topx + 8d - 1d - x, topy + 13d - 1d - y, color);
				}
			}
		}
	}

	public static double GetTextWidth(char [] text){
		double charWidth, spacing, width;

		charWidth = 8d;
		spacing = 2d;

		if(text.length == 0d){
			width = 0d;
		}else{
			width = text.length*charWidth + (text.length - 1d)*spacing;
		}

		return width;
	}

	public static double GetTextHeight(char [] text){
		return 13d;
	}

  public static void delete(Object object){
    // Java has garbage collection.
  }
}
